DROP TABLE IF EXISTS MYS_INFORMA_SCHEMA.enabled_roles;
CREATE TABLE MYS_INFORMA_SCHEMA.enabled_roles (
  ROLE_NAME varchar(255) DEFAULT NULL,
  ROLE_HOST varchar(255) DEFAULT NULL,
  IS_DEFAULT varchar(3)  DEFAULT NULL,
  IS_MANDATORY varchar(3)  NOT NULL DEFAULT ''
) ;

DROP TABLE IF EXISTS MYS_INFORMA_SCHEMA.files;
CREATE TABLE MYS_INFORMA_SCHEMA.files (
  FILE_ID bigint DEFAULT NULL,
  FILE_NAME text  ,
  FILE_TYPE varchar(256)  DEFAULT NULL,
  TABLESPACE_NAME varchar(268)  NOT NULL,
  TABLE_CATALOG char(10)  NOT NULL DEFAULT '',
  TABLE_SCHEMA bytea DEFAULT NULL,
  TABLE_NAME bytea DEFAULT NULL,
  LOGFILE_GROUP_NAME varchar(256)  DEFAULT NULL,
  LOGFILE_GROUP_NUMBER bigint DEFAULT NULL,
  ENGINE varchar(64)  NOT NULL,
  FULLTEXT_KEYS bytea DEFAULT NULL,
  DELETED_ROWS bytea DEFAULT NULL,
  UPDATE_COUNT bytea DEFAULT NULL,
  FREE_EXTENTS bigint DEFAULT NULL,
  TOTAL_EXTENTS bigint DEFAULT NULL,
  EXTENT_SIZE bigint DEFAULT NULL,
  INITIAL_SIZE bigint DEFAULT NULL,
  MAXIMUM_SIZE bigint DEFAULT NULL,
  AUTOEXTEND_SIZE bigint DEFAULT NULL,
  CREATION_TIME bytea DEFAULT NULL,
  LAST_UPDATE_TIME bytea DEFAULT NULL,
  LAST_ACCESS_TIME bytea DEFAULT NULL,
  RECOVER_TIME bytea DEFAULT NULL,
  TRANSACTION_COUNTER bytea DEFAULT NULL,
  VERSION bigint DEFAULT NULL,
  ROW_FORMAT varchar(256)  DEFAULT NULL,
  TABLE_ROWS bytea DEFAULT NULL,
  AVG_ROW_LENGTH bytea DEFAULT NULL,
  DATA_LENGTH bytea DEFAULT NULL,
  MAX_DATA_LENGTH bytea DEFAULT NULL,
  INDEX_LENGTH bytea DEFAULT NULL,
  DATA_FREE bigint DEFAULT NULL,
  CREATE_TIME bytea DEFAULT NULL,
  UPDATE_TIME bytea DEFAULT NULL,
  CHECK_TIME bytea DEFAULT NULL,
  CHECKSUM bytea DEFAULT NULL,
  STATUS varchar(256)  DEFAULT NULL,
  EXTRA varchar(256)  DEFAULT NULL
) ;

DROP TABLE IF EXISTS MYS_INFORMA_SCHEMA.innodb_buffer_page;
CREATE TABLE MYS_INFORMA_SCHEMA.innodb_buffer_page (
  POOL_ID bigint NOT NULL DEFAULT '0',
  BLOCK_ID bigint NOT NULL DEFAULT '0',
  SPACE bigint NOT NULL DEFAULT '0',
  PAGE_NUMBER bigint NOT NULL DEFAULT '0',
  PAGE_TYPE varchar(64)  DEFAULT NULL,
  FLUSH_TYPE bigint NOT NULL DEFAULT '0',
  FIX_COUNT bigint NOT NULL DEFAULT '0',
  IS_HASHED varchar(3)  DEFAULT NULL,
  NEWEST_MODIFICATION bigint NOT NULL DEFAULT '0',
  OLDEST_MODIFICATION bigint NOT NULL DEFAULT '0',
  ACCESS_TIME bigint NOT NULL DEFAULT '0',
  TABLE_NAME varchar(1024)  DEFAULT NULL,
  INDEX_NAME varchar(1024)  DEFAULT NULL,
  NUMBER_RECORDS bigint NOT NULL DEFAULT '0',
  DATA_SIZE bigint NOT NULL DEFAULT '0',
  COMPRESSED_SIZE bigint NOT NULL DEFAULT '0',
  PAGE_STATE varchar(64)  DEFAULT NULL,
  IO_FIX varchar(64)  DEFAULT NULL,
  IS_OLD varchar(3)  DEFAULT NULL,
  FREE_PAGE_CLOCK bigint NOT NULL DEFAULT '0',
  IS_STALE varchar(3)  DEFAULT NULL
) ;

DROP TABLE IF EXISTS MYS_INFORMA_SCHEMA.innodb_buffer_page_lru;
CREATE TABLE MYS_INFORMA_SCHEMA.innodb_buffer_page_lru (
  POOL_ID bigint NOT NULL DEFAULT '0',
  LRU_POSITION bigint NOT NULL DEFAULT '0',
  SPACE bigint NOT NULL DEFAULT '0',
