  PAGE_TYPE varchar(64)  DEFAULT NULL,
  FLUSH_TYPE bigint NOT NULL DEFAULT '0',
  FIX_COUNT bigint NOT NULL DEFAULT '0',
  IS_HASHED varchar(3)  DEFAULT NULL,
  NEWEST_MODIFICATION bigint NOT NULL DEFAULT '0',
  OLDEST_MODIFICATION bigint NOT NULL DEFAULT '0',
  ACCESS_TIME bigint NOT NULL DEFAULT '0',
  TABLE_NAME varchar(1024)  DEFAULT NULL,
  INDEX_NAME varchar(1024)  DEFAULT NULL,
  NUMBER_RECORDS bigint NOT NULL DEFAULT '0',
  DATA_SIZE bigint NOT NULL DEFAULT '0',
  COMPRESSED_SIZE bigint NOT NULL DEFAULT '0',
  COMPRESSED varchar(3)  DEFAULT NULL,
  IO_FIX varchar(64)  DEFAULT NULL,
  IS_OLD varchar(3)  DEFAULT NULL,
  FREE_PAGE_CLOCK bigint NOT NULL DEFAULT '0'
) ;

DROP TABLE IF EXISTS MYS_INFORMA_SCHEMA.innodb_buffer_pool_stats;
CREATE TABLE MYS_INFORMA_SCHEMA.innodb_buffer_pool_stats (
  POOL_ID bigint NOT NULL DEFAULT '0',
