  NUMBER_PAGES_CREATED bigint NOT NULL DEFAULT '0',
  NUMBER_PAGES_WRITTEN bigint NOT NULL DEFAULT '0',
  PAGES_READ_RATE float NOT NULL DEFAULT '0',
  PAGES_CREATE_RATE float NOT NULL DEFAULT '0',
  PAGES_WRITTEN_RATE float NOT NULL DEFAULT '0',
  NUMBER_PAGES_GET bigint NOT NULL DEFAULT '0',
