  READ_AHEAD_RATE float NOT NULL DEFAULT '0',
  READ_AHEAD_EVICTED_RATE float NOT NULL DEFAULT '0',
  LRU_IO_TOTAL bigint NOT NULL DEFAULT '0',
  LRU_IO_CURRENT bigint NOT NULL DEFAULT '0',
  UNCOMPRESS_TOTAL bigint NOT NULL DEFAULT '0',
  UNCOMPRESS_CURRENT bigint NOT NULL DEFAULT '0'
) ;
