DROP TABLE IF EXISTS MYS_INFORMA_SCHEMA.optimizer_trace;
CREATE TABLE MYS_INFORMA_SCHEMA.optimizer_trace (
  QUERY text  NOT NULL,
  TRACE text  NOT NULL,
  MISSING_BYTES_BEYOND_MAX_MEM_SIZE int NOT NULL DEFAULT '0',
  INSUFFICIENT_PRIVILEGES int NOT NULL DEFAULT '0'
) ;

DROP TABLE IF EXISTS MYS_INFORMA_SCHEMA.processlist;
CREATE TABLE MYS_INFORMA_SCHEMA.processlist (
  ID bigint NOT NULL DEFAULT '0',
  "user" varchar(32)  NOT NULL DEFAULT '',
  HOST varchar(261)  NOT NULL DEFAULT '',
  DB varchar(64)  DEFAULT NULL,
  COMMAND varchar(16)  NOT NULL DEFAULT '',
  TIME int NOT NULL DEFAULT '0',
  STATE varchar(64)  DEFAULT NULL,
  INFO text 
) ;
