DROP TABLE IF EXISTS performance_schema.accounts;
CREATE TABLE performance_schema.accounts (
  "user" char(32) DEFAULT NULL,
  HOST char(255) DEFAULT NULL,
  CURRENT_CONNECTIONS bigint NOT NULL,
  TOTAL_CONNECTIONS bigint NOT NULL
  --UNIQUE ACCOUNT (USER,HOST)
);

CREATE TYPE performance_schema.enum_bin_log_trans_comp_stats_log_type as enum('BINARY','RELAY'); 
DROP TABLE IF EXISTS performance_schema.binary_log_transaction_compression_stats;
CREATE TABLE performance_schema.binary_log_transaction_compression_stats (
  LOG_TYPE performance_schema.enum_bin_log_trans_comp_stats_log_type NOT NULL ,
  --LOG_TYPE enum('BINARY','RELAY') NOT NULL ,
  COMPRESSION_TYPE varchar(64) NOT NULL ,
  TRANSACTION_COUNTER bigint NOT NULL ,
  COMPRESSED_BYTES_COUNTER bigint NOT NULL ,
  UNCOMPRESSED_BYTES_COUNTER bigint NOT NULL ,
  COMPRESSION_PERCENTAGE mysql.smallint NOT NULL ,
  FIRST_TRANSACTION_ID text ,
  FIRST_TRANSACTION_COMPRESSED_BYTES bigint NOT NULL ,
  FIRST_TRANSACTION_UNCOMPRESSED_BYTES bigint NOT NULL ,
  FIRST_TRANSACTION_TIMESTAMP timestamp(6) NULL DEFAULT NULL ,
  LAST_TRANSACTION_ID text ,
  LAST_TRANSACTION_COMPRESSED_BYTES bigint NOT NULL ,
  LAST_TRANSACTION_UNCOMPRESSED_BYTES bigint NOT NULL ,
  LAST_TRANSACTION_TIMESTAMP timestamp(6) NULL DEFAULT NULL 
);

DROP TABLE IF EXISTS performance_schema.cond_instances;
CREATE TABLE performance_schema.cond_instances (
  NAME varchar(128) NOT NULL,
  OBJECT_INSTANCE_BEGIN bigint NOT NULL,
  PRIMARY KEY (OBJECT_INSTANCE_BEGIN)
);
CREATE INDEX name on performance_schema.cond_instances(name);

DROP TABLE IF EXISTS performance_schema.data_lock_waits;
CREATE TABLE performance_schema.data_lock_waits (
  ENGINE varchar(32) NOT NULL,
  REQUESTING_ENGINE_LOCK_ID varchar(128) NOT NULL,
  REQUESTING_ENGINE_TRANSACTION_ID bigint DEFAULT NULL,
  REQUESTING_THREAD_ID bigint DEFAULT NULL,
  REQUESTING_EVENT_ID bigint DEFAULT NULL,
  REQUESTING_OBJECT_INSTANCE_BEGIN bigint NOT NULL,
  BLOCKING_ENGINE_LOCK_ID varchar(128) NOT NULL,
  BLOCKING_ENGINE_TRANSACTION_ID bigint DEFAULT NULL,
  BLOCKING_THREAD_ID bigint DEFAULT NULL,
  BLOCKING_EVENT_ID bigint DEFAULT NULL,
  BLOCKING_OBJECT_INSTANCE_BEGIN bigint NOT NULL
);
CREATE INDEX REQUESTING_ENGINE_LOCK_ID on performance_schema.data_lock_waits(REQUESTING_ENGINE_LOCK_ID, ENGINE);
CREATE INDEX BLOCKING_ENGINE_LOCK_ID on performance_schema.data_lock_waits(BLOCKING_ENGINE_LOCK_ID, ENGINE);
CREATE INDEX REQUESTING_ENGINE_TRANSACTION_ID on performance_schema.data_lock_waits(REQUESTING_ENGINE_TRANSACTION_ID, ENGINE);
CREATE INDEX BLOCKING_ENGINE_TRANSACTION_ID on performance_schema.data_lock_waits(BLOCKING_ENGINE_TRANSACTION_ID, ENGINE);
CREATE INDEX REQUESTING_THREAD_ID on performance_schema.data_lock_waits(REQUESTING_THREAD_ID, REQUESTING_EVENT_ID);
CREATE INDEX BLOCKING_THREAD_ID on performance_schema.data_lock_waits(BLOCKING_THREAD_ID, BLOCKING_EVENT_ID);

DROP TABLE IF EXISTS performance_schema.data_locks;
CREATE TABLE performance_schema.data_locks (
  ENGINE varchar(32) NOT NULL,
  ENGINE_LOCK_ID varchar(128) NOT NULL,
  ENGINE_TRANSACTION_ID bigint DEFAULT NULL,
  THREAD_ID bigint DEFAULT NULL,
  EVENT_ID bigint DEFAULT NULL,
  OBJECT_SCHEMA varchar(64) DEFAULT NULL,
  OBJECT_NAME varchar(64) DEFAULT NULL,
  PARTITION_NAME varchar(64) DEFAULT NULL,
  SUBPARTITION_NAME varchar(64) DEFAULT NULL,
  INDEX_NAME varchar(64) DEFAULT NULL,
  OBJECT_INSTANCE_BEGIN bigint NOT NULL,
  LOCK_TYPE varchar(32) NOT NULL,
  LOCK_MODE varchar(32) NOT NULL,
  LOCK_STATUS varchar(32) NOT NULL,
  LOCK_DATA varchar(8192) DEFAULT NULL,
  PRIMARY KEY (ENGINE_LOCK_ID,ENGINE)
);
CREATE INDEX ENGINE_TRANSACTION_ID on performance_schema.data_locks(ENGINE_TRANSACTION_ID, ENGINE);
CREATE INDEX THREAD_ID on performance_schema.data_locks(THREAD_ID, EVENT_ID);
CREATE INDEX OBJECT_SCHEMA on performance_schema.data_locks(OBJECT_SCHEMA, OBJECT_NAME, PARTITION_NAME, SUBPARTITION_NAME);

create type performance_schema.enum_error_log_prio as enum('System','Error','Warning','Note');
DROP TABLE IF EXISTS performance_schema.error_log;
CREATE TABLE performance_schema.error_log (
  LOGGED timestamp(6) NOT NULL,
  THREAD_ID bigint DEFAULT NULL,
  PRIO performance_schema.enum_error_log_prio NOT NULL,
  --PRIO enum('System','Error','Warning','Note') NOT NULL,
  ERROR_CODE varchar(10) DEFAULT NULL,
  SUBSYSTEM varchar(7) DEFAULT NULL,
  DATA text NOT NULL,
  PRIMARY KEY (LOGGED)
);
CREATE INDEX THREAD_ID_ on performance_schema.error_log(THREAD_ID);
CREATE INDEX PRIO on performance_schema.error_log(PRIO);
CREATE INDEX ERROR_CODE on performance_schema.error_log(ERROR_CODE);
CREATE INDEX SUBSYSTEM on performance_schema.error_log(SUBSYSTEM);

DROP TABLE IF EXISTS performance_schema.events_errors_summary_by_account_by_error;
CREATE TABLE performance_schema.events_errors_summary_by_account_by_error (
  "user" char(32) DEFAULT NULL,
  HOST char(255) DEFAULT NULL,
  ERROR_NUMBER int DEFAULT NULL,
  ERROR_NAME varchar(64) DEFAULT NULL,
  SQL_STATE varchar(5) DEFAULT NULL,
  SUM_ERROR_RAISED bigint NOT NULL,
  SUM_ERROR_HANDLED bigint NOT NULL,
  FIRST_SEEN timestamp NULL DEFAULT NULL,
  LAST_SEEN timestamp NULL DEFAULT NULL
  --UNIQUE ACCOUNT (USER,HOST,ERROR_NUMBER)
);

DROP TABLE IF EXISTS performance_schema.events_errors_summary_by_host_by_error;
CREATE TABLE performance_schema.events_errors_summary_by_host_by_error (
  HOST char(255) DEFAULT NULL,
  ERROR_NUMBER int DEFAULT NULL,
  ERROR_NAME varchar(64) DEFAULT NULL,
  SQL_STATE varchar(5) DEFAULT NULL,
  SUM_ERROR_RAISED bigint NOT NULL,
  SUM_ERROR_HANDLED bigint NOT NULL,
  FIRST_SEEN timestamp NULL DEFAULT NULL,
  LAST_SEEN timestamp NULL DEFAULT NULL
);
CREATE UNIQUE INDEX HOST ON performance_schema.events_errors_summary_by_host_by_error(HOST,ERROR_NUMBER);

DROP TABLE IF EXISTS performance_schema.events_errors_summary_by_thread_by_error;
CREATE TABLE performance_schema.events_errors_summary_by_thread_by_error (
  THREAD_ID bigint NOT NULL,
  ERROR_NUMBER int DEFAULT NULL,
  ERROR_NAME varchar(64) DEFAULT NULL,
  SQL_STATE varchar(5) DEFAULT NULL,
  SUM_ERROR_RAISED bigint NOT NULL,
  SUM_ERROR_HANDLED bigint NOT NULL,
  FIRST_SEEN timestamp NULL DEFAULT NULL,
  LAST_SEEN timestamp NULL DEFAULT NULL
);
CREATE UNIQUE INDEX THREAD_ID_eesbtbe ON performance_schema.events_errors_summary_by_thread_by_error(THREAD_ID,ERROR_NUMBER);

DROP TABLE IF EXISTS performance_schema.events_errors_summary_by_user_by_error;
CREATE TABLE performance_schema.events_errors_summary_by_user_by_error (
  "user" char(32) DEFAULT NULL,
  ERROR_NUMBER int DEFAULT NULL,
  ERROR_NAME varchar(64) DEFAULT NULL,
  SQL_STATE varchar(5) DEFAULT NULL,
  SUM_ERROR_RAISED bigint NOT NULL,
  SUM_ERROR_HANDLED bigint NOT NULL,
  FIRST_SEEN timestamp NULL DEFAULT NULL,
  LAST_SEEN timestamp NULL DEFAULT NULL
  --UNIQUE USER_eesbube (USER,ERROR_NUMBER)
);

DROP TABLE IF EXISTS performance_schema.events_errors_summary_global_by_error;
CREATE TABLE performance_schema.events_errors_summary_global_by_error (
  ERROR_NUMBER int DEFAULT NULL,
  ERROR_NAME varchar(64) DEFAULT NULL,
  SQL_STATE varchar(5) DEFAULT NULL,
  SUM_ERROR_RAISED bigint NOT NULL,
  SUM_ERROR_HANDLED bigint NOT NULL,
  FIRST_SEEN timestamp NULL DEFAULT NULL,
