-- 因为mysql是一个公共schema，
-- 所以将mysql schema下的非表对象都移到mys_informa_schema下
create type mysql.enum_mysql_user as enum('N','Y');
create type mysql.enum_mysql_user_ssl_type as enum('','ANY','X509','SPECIFIED');
DROP TABLE IF EXISTS mysql.user;
CREATE TABLE mysql.user (
  Host char(255) NOT NULL DEFAULT '',
  "user" char(32) NOT NULL DEFAULT '',
  Select_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Insert_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Update_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Delete_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Create_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Drop_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Reload_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Shutdown_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Process_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  File_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Grant_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  References_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Index_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Alter_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Show_db_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Super_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Create_tmp_table_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Lock_tables_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Execute_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Repl_slave_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Repl_client_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Create_view_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Show_view_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Create_routine_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Alter_routine_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Create_user_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Event_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Trigger_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Create_tablespace_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  ssl_type mysql.enum_mysql_user_ssl_type NOT NULL DEFAULT '',
  --ssl_type enum('','ANY','X509','SPECIFIED') NOT NULL DEFAULT '',
  ssl_cipher bytea NOT NULL,
  x509_issuer bytea NOT NULL,
  x509_subject bytea NOT NULL,
  max_questions int NOT NULL DEFAULT '0',
  max_updates int NOT NULL DEFAULT '0',
  max_connections int NOT NULL DEFAULT '0',
  max_user_connections int NOT NULL DEFAULT '0',
  plugin char(64) NOT NULL DEFAULT 'caching_sha2_password',
  authentication_string text,
  password_expired mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  password_last_changed timestamp NULL DEFAULT NULL,
  password_lifetime mysql.smallint DEFAULT NULL,
  account_locked mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Create_role_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Drop_role_priv mysql.enum_mysql_user NOT NULL DEFAULT 'N',
  Password_reuse_history mysql.smallint DEFAULT NULL,
  Password_reuse_time mysql.smallint DEFAULT NULL,
  Password_require_current mysql.enum_mysql_user DEFAULT NULL,
  User_attributes varchar(1024) DEFAULT NULL
  --PRIMARY KEY (Host,User)
);

drop view if exists mys_informa_schema.views;
create view mys_informa_schema.views as
select
    'def'::varchar(256) as TABLE_CATALOG,
    vw.schemaname::varchar(256) as Table_Schema,
    vw.viewname::varchar(256) as Table_Name,
    'VIEW'::varchar(256) as Table_Type,
    vw.definition::varchar(256) as VIEW_DEFINITION,
    'NONE'::varchar(256) as Check_option,
    'YES'::varchar(256) as IS_UPDATABLE,
    (vw.viewowner || '@%')::varchar(256) as Definer,
    'DEFINER'::varchar(256) as Security_type,
    'utf8mb4'::varchar(256) as CHARACTER_SET_CLIENT,
    'utf8mb4_general_ci'::varchar(256) as COLLATION_CONNECTION
from pg_views vw
order by 1;

create table mys_informa_schema.events(
    EVENT_CATALOG varchar(256),
    EVENT_SCHEMA varchar(256),
    EVENT_NAME varchar(256),
    DEFINER varchar(256),
    TIME_ZONE varchar(256),
    EVENT_BODY varchar(256),
    EVENT_DEFINITION varchar(256),
    EVENT_TYPE varchar(256),
    EXECUTE_AT varchar(256),
    INTERVAL_VALUE varchar(256),
    INTERVAL_FIELD varchar(256),
    SQL_MODE varchar(256),
    STARTS varchar(256),
    ENDS varchar(256),
    STATUS varchar(256),
    ON_COMPLETION varchar(256),
    CREATED varchar(256),
    LAST_ALTERED varchar(256),
    LAST_EXECUTED varchar(256),
    EVENT_COMMENT varchar(256),
    ORIGINATOR varchar(256),
    CHARACTER_SET_CLIENT varchar(256),
    COLLATION_CONNECTION varchar(256),
    DATABASE_COLLATION varchar(256)
);

create table performance_schema.user_variables_by_thread(
    THREAD_ID bigint,
    VARIABLE_NAME varchar(256),
    VARIABLE_VALUE text
);

create table mys_informa_schema.table_constraints(
    CONSTRAINT_CATALOG varchar(256),
    CONSTRAINT_SCHEMA varchar(256),
    CONSTRAINT_NAME varchar(256),
    TABLE_SCHEMA varchar(256),
    TABLE_NAME varchar(256),
    CONSTRAINT_TYPE varchar(256)
);

create table mys_informa_schema.charsets(
    Charset varchar(64),
    Description varchar(256),
    "default collation" varchar(256),
    Maxlen int
);
insert into mys_informa_schema.charsets values('utf8mb4', 'UTF-8 Unicode', 'utf8mb4_general_ci', 4);

create view mys_informa_schema.schemata as
select
    'def'::varchar(256) as CATALOG_NAME,
    sch.nspname::varchar(256) as SCHEMA_NAME,
    'utf8mb4'::varchar(256) as DEFAULT_CHARACTER_SET_NAME,
    'utf8mb4_general_ci'::varchar(256) as DEFAULT_COLLATION_NAME,
    'NULL'::varchar(256) as SQL_PATH
from pg_catalog.pg_namespace sch
WHERE sch.nspname !~ '^pg_'
ORDER BY 1;

