DROP FUNCTION IF EXISTS mysql.set_system_variable(pg_catalog.text, pg_catalog.text, pg_catalog.bool) cascade;
CREATE OR REPLACE FUNCTION mysql.set_system_variable(pg_catalog.text, pg_catalog.text, pg_catalog.bool)
RETURNS pg_catalog.bool
AS '$libdir/mysm', 'setSystemVariable'
LANGUAGE C IMMUTABLE;

DROP FUNCTION IF EXISTS mysql.set_system_session_variable(pg_catalog.text, pg_catalog.anycompatible) cascade;
CREATE OR REPLACE FUNCTION mysql.set_system_session_variable(pg_catalog.text, pg_catalog.anycompatible)
RETURNS void
AS
$$
DECLARE
    system_var_name pg_catalog.text;
    system_var_value pg_catalog.text;
    is_session_sys_var pg_catalog.bool;
    set_ret pg_catalog.bool;
BEGIN
    system_var_name := $1;
    system_var_value := $2::text;
    is_session_sys_var := true;
    set_ret := mysql.set_system_variable(system_var_name, system_var_value, is_session_sys_var);
    if set_ret = true then
        -- do nothing;
    else
        raise exception 'Unknown system variable ''%''', system_var_name;
    end if;
END
$$
VOLATILE LANGUAGE 'plpgsql';

DROP FUNCTION IF EXISTS mysql.set_system_names_variable(pg_catalog.text);
CREATE OR REPLACE FUNCTION mysql.set_system_names_variable(pg_catalog.text)
RETURNS void
AS
$$
DECLARE
    system_var_name pg_catalog.text;
    system_var_value pg_catalog.text;
    is_session_sys_var pg_catalog.bool;
    set_ret pg_catalog.bool;
BEGIN
    system_var_value := $1::text;
    is_session_sys_var := true;

    system_var_name := 'character_set_client';
    set_ret := mysql.set_system_variable(system_var_name, system_var_value, is_session_sys_var);
    if set_ret = true then
        -- do nothing;
    else
        raise exception 'Unknown system variable ''%''', system_var_name;
    end if;

    system_var_name := 'character_set_results';
    set_ret := mysql.set_system_variable(system_var_name, system_var_value, is_session_sys_var);
    if set_ret = true then
        -- do nothing;
    else
        raise exception 'Unknown system variable ''%''', system_var_name;
    end if;

    system_var_name := 'character_set_connection';
    set_ret := mysql.set_system_variable(system_var_name, system_var_value, is_session_sys_var);
    if set_ret = true then
        -- do nothing;
    else
        raise exception 'Unknown system variable ''%''', system_var_name;
    end if;
END
$$
VOLATILE LANGUAGE 'plpgsql';

DROP FUNCTION IF EXISTS mysql.set_system_global_variable(pg_catalog.text, pg_catalog.anycompatible) cascade;
CREATE OR REPLACE FUNCTION mysql.set_system_global_variable(pg_catalog.text, pg_catalog.anycompatible)
RETURNS void
AS
$$
DECLARE
    system_var_name pg_catalog.text;
    system_var_value pg_catalog.text;
    is_session_sys_var pg_catalog.bool;
    set_ret pg_catalog.bool;
BEGIN
    system_var_name := $1;
    system_var_value := $2::text;
    is_session_sys_var := false;
    set_ret := mysql.set_system_variable(system_var_name, system_var_value, is_session_sys_var);
    if set_ret = true then
        -- do nothing;
    else
        raise exception 'Unknown system variable ''%''', system_var_name;
    end if;
END
$$
VOLATILE LANGUAGE 'plpgsql';

DROP FUNCTION IF EXISTS mysql.get_system_variable(pg_catalog.text, pg_catalog.bool) cascade;
CREATE OR REPLACE FUNCTION mysql.get_system_variable(pg_catalog.text, pg_catalog.bool)
RETURNS pg_catalog.text
AS '$libdir/mysm', 'getSystemVariable'
LANGUAGE C STRICT IMMUTABLE;

DROP FUNCTION IF EXISTS mysql.get_system_session_variable(pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.get_system_session_variable(pg_catalog.text)
RETURNS text
AS
$$
DECLARE
    get_ret pg_catalog.text;
    system_var_name pg_catalog.text;
    is_session_sys_var pg_catalog.bool;
BEGIN
    system_var_name := $1;
    is_session_sys_var := true;

    get_ret := mysql.get_system_variable(system_var_name, is_session_sys_var);
    return get_ret;
END
$$
VOLATILE LANGUAGE 'plpgsql';

DROP FUNCTION IF EXISTS mysql.get_system_global_variable(pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.get_system_global_variable(pg_catalog.text)
RETURNS text
AS
$$
DECLARE
    get_ret pg_catalog.text;
    system_var_name pg_catalog.text;
    is_session_sys_var pg_catalog.bool;
BEGIN
    system_var_name := $1;
    is_session_sys_var := false;

    get_ret := mysql.get_system_variable(system_var_name, is_session_sys_var);
    return get_ret;
END
$$
VOLATILE LANGUAGE 'plpgsql';

drop view if exists mys_informa_schema.tables cascade;
create view mys_informa_schema.tables as
select
    'def'::varchar(256) as TABLE_CATALOG,
    (select ns.nspname from pg_catalog.pg_namespace ns where ns.oid = cl.relnamespace)::varchar(256) as Table_Schema,
    cl.relname::varchar(256) as Table_Name,
    'BASE TABLE'::varchar(256) as Table_Type,
    'InnoDB'::varchar(256) as Engine,
    10::bigint as Version,
    'Dynamic'::varchar(256) as Row_format,
    cl.reltuples::bigint as Table_Rows,
    100::bigint as Avg_row_length,
    16384::bigint as Data_length,
    16384::bigint as Max_data_length,
    16384::bigint as Index_length,
    16384::bigint as Data_free,
    (select count(*) from pg_class where relname like concat(cl.relname, '%') and relkind = 'S')::bigint as Auto_increment,
    NULL::bigint as Create_time,
    NULL::bigint as Update_time,
    NULL::timestamp as Check_time,
    'utf8mb4_general_ci'::varchar(256) as Table_Collation,
    NULL::bigint as Checksum,
    ''::varchar(256) as Create_options,
    (select ds.description from pg_description ds where ds.objoid = cl.oid and objsubid = 0)::varchar(512) as Table_Comment
from pg_catalog.pg_class cl
where cl.oid >= 16384 and (cl.relkind = 'r' or cl.relkind = 'p')
order by 1;

DROP FUNCTION IF EXISTS mysql.show_create_function(pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_create_function(pg_catalog.text, pg_catalog.text)
RETURNS setof RECORD
AS
$$
DECLARE
    schName pg_catalog.varchar(128);
    funcName pg_catalog.varchar(128);
    func RECORD;
    recordNum pg_catalog.int4;
BEGIN
    schName := $1;
    funcName := $2;
    recordNum := 0;

    FOR func IN
        select
            Name,
            @@sql_mode::varchar(256) as sql_mode,
            Define,
            Character_set_client,
            Collation_connection,
            Database_Collation
        FROM mys_informa_schema.functions
        WHERE Db = schName and Name = funcName
    LOOP
        recordNum := recordNum + 1;
        return next func;
    END LOOP;

    if (recordNum = 0) then
        raise exception 'FUNCTION % does not exist', funcName;
    end if;

    return;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

DROP FUNCTION IF EXISTS mysql.show_create_procedure(pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_create_procedure(pg_catalog.text, pg_catalog.text)
RETURNS setof RECORD
AS
$$
DECLARE
    schName pg_catalog.varchar(128);
    procName pg_catalog.varchar(128);
    proc RECORD;
    recordNum pg_catalog.int4;
BEGIN
    schName := $1;
    procName := $2;
    recordNum := 0;

    FOR proc IN
        select
            Name,
            @@sql_mode::varchar(256) as sql_mode,
            Define,
            Character_set_client,
            Collation_connection,
            Database_Collation
        FROM mys_informa_schema.procedures
        WHERE Db = schName and Name = procName
    LOOP
        recordNum := recordNum + 1;
        return next proc;
    END LOOP;

    if (recordNum = 0) then
        raise exception 'PROCEDURE % does not exist', procName;
    end if;

    return;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mysql.get_proc_def(procName pg_catalog.text,
                                                procOwner pg_catalog.text,
                                                proargtypes pg_catalog.oidvector,
                                                proallargtypes pg_catalog.oid[],
                                                proargmodes "char"[],
                                                proargnames pg_catalog.text[],
                                                prosrc pg_catalog.text)
RETURNS pg_catalog.text
AS
$$
DECLARE
    ret pg_catalog.text;
    allArgNum pg_catalog.int4;
    argIndex pg_catalog.int4;
    argTypes pg_catalog.int4[];
BEGIN
    ret := "CREATE DEFINER=`";
    ret := pg_catalog.concat(ret, procOwner);
    ret := pg_catalog.concat(ret, "`@`%` PROCEDURE `");
    ret := pg_catalog.concat(ret, procName);
    ret := pg_catalog.concat(ret, "`(");
    if (proallargtypes is not null) then
        allArgNum := array_length(proallargtypes, 1);
        argIndex := 1;
        LOOP
            if (1 < argIndex) then
                ret := pg_catalog.concat(ret, ", ");
            end if;

            if (proargmodes[argIndex] = 'i') then
                ret := pg_catalog.concat(ret, "IN");
            elsif (proargmodes[argIndex] = 'b') then
                ret := pg_catalog.concat(ret, "INOUT");
            else
                ret := pg_catalog.concat(ret, "OUT");
            end if;

            ret := pg_catalog.concat(ret, " ");
            ret := pg_catalog.concat(ret, proargnames[argIndex]);

            ret := pg_catalog.concat(ret, " ");
            ret := pg_catalog.concat(ret, proallargtypes[argIndex]::regType::pg_catalog.text);

            argIndex := argIndex + 1;

            EXIT WHEN argIndex > allArgNum;
        END LOOP;
    else
        argTypes := string_to_array(proargtypes::text, ' ');
        allArgNum := array_length(argTypes, 1);
        if (0 < allArgNum) then
            argIndex := 1;
            LOOP
                if (1 < argIndex) then
                    ret := pg_catalog.concat(ret, ",");
                end if;

                ret := pg_catalog.concat(ret, " IN");

                ret := pg_catalog.concat(ret, " ");
                ret := pg_catalog.concat(ret, proargnames[argIndex]);

                ret := pg_catalog.concat(ret, " ");
                ret := pg_catalog.concat(ret, argTypes[argIndex]::regType::pg_catalog.text);

                argIndex := argIndex + 1;
                EXIT WHEN argIndex > allArgNum;
            END LOOP;
        end if;
    end if;
    ret := pg_catalog.concat(ret, ")\n");

    ret := pg_catalog.concat(ret, prosrc);

    RETURN ret;
END
$$
IMMUTABLE LANGUAGE PLPGSQL;

CREATE OR REPLACE FUNCTION mysql.get_func_def(funcName text,
                                              procOwner pg_catalog.text,
                                              prorettype pg_catalog.oid,
                                              proargtypes pg_catalog.oidvector,
                                              proargnames pg_catalog.text[],
                                              prosrc text)
RETURNS text
AS
$$
DECLARE
    ret pg_catalog.text;
    argTypes pg_catalog.int4[];
    allArgNum pg_catalog.int4;
    argIndex pg_catalog.int4;
BEGIN
    ret := "CREATE DEFINER=`";
    ret := pg_catalog.concat(ret, procOwner);
    ret := pg_catalog.concat(ret, "`@`%` FUNCTION `");
    ret := pg_catalog.concat(ret, funcName);
    ret := pg_catalog.concat(ret, "`(");
    argTypes := string_to_array(proargtypes::text, ' ');
    allArgNum := array_length(argTypes, 1);
    argIndex := 1;
    if (0 < allArgNum) then
        LOOP
            if (1 < argIndex) then
                ret := pg_catalog.concat(ret, ", ");
            end if;

            ret := pg_catalog.concat(ret, proargnames[argIndex]);
            ret := pg_catalog.concat(ret, " ");
            ret := pg_catalog.concat(ret, argTypes[argIndex]::regType::text);

            argIndex := argIndex + 1;
            EXIT WHEN argIndex > allArgNum;
        END LOOP;
    end if;
    ret := pg_catalog.concat(ret, ")");

    -- ret := pg_catalog.concat(ret, "\n");
    ret := pg_catalog.concat(ret, " ");
    ret := pg_catalog.concat(ret, "RETURNS ", prorettype::regType::text);

    ret := pg_catalog.concat(ret, "\n");
    ret := pg_catalog.concat(ret, prosrc);

    RETURN ret;
END
$$
IMMUTABLE LANGUAGE PLPGSQL;

DROP VIEW IF EXISTS mys_informa_schema.functions;
CREATE VIEW mys_informa_schema.functions AS
SELECT
    (select ns.nspname from pg_namespace ns where ns.oid = pc.pronamespace)::varchar(256) as Db,
    pc.proname::varchar(256) as Name,
    'FUNCTION'::varchar(256) as Type,
    (mysql.get_func_def(pc.proname, pc.proowner::regrole::pg_catalog.text, pc.prorettype, pc.proargtypes, pc.proargnames, pc.prosrc))::text as Define,
    (select au.rolname from pg_authid au where au.oid = pc.proowner)::varchar(256) as Definer,
    null::varchar(256) as Modified,
    null::varchar(256) as Created,
    'DEFINER'::varchar(256) as Security_type,
    ''::varchar(512) as Comment,
    'utf8mb4'::varchar(128) as Character_set_client,
    'utf8mb4_general_ci'::varchar(128) as Collation_connection,
    'utf8mb4_general_ci'::varchar(128) as Database_Collation
FROM pg_proc pc
WHERE pc.prokind = 'f' and substring(pc.proname from 1 for 21) != 'func_reset_serial_for';

DROP VIEW IF EXISTS mys_informa_schema.procedures;
CREATE VIEW mys_informa_schema.procedures AS
SELECT
    (select ns.nspname from pg_namespace ns where ns.oid = pc.pronamespace)::varchar(256) as Db,
    pc.proname::varchar(256) as Name,
    'PROCEDURE'::varchar(256) as Type,
    (mysql.get_proc_def(pc.proname, pc.proowner::regrole::pg_catalog.text, pc.proargtypes, pc.proallargtypes, pc.proargmodes, pc.proargnames, pc.prosrc))::text as Define,
    (select au.rolname from pg_authid au where au.oid = pc.proowner)::varchar(256) as Definer,
    '2022-10-21 10:20:30'::varchar(256) as Modified,
    '2022-10-20 10:20:30'::varchar(256) as Created,
    'DEFINER'::varchar(256) as Security_type,
    ''::varchar(512) as Comment,
    'utf8mb4'::varchar(128) as Character_set_client,
    'utf8mb4_general_ci'::varchar(128) as Collation_connection,
    'utf8mb4_general_ci'::varchar(128) as Database_Collation
FROM pg_proc pc
WHERE pc.prokind = 'p' and substring(pc.proname from 1 for 21) != 'func_reset_serial_for';

DROP FUNCTION IF EXISTS mysql.current_user() cascade;
CREATE OR REPLACE FUNCTION mysql.current_user()
RETURNS text
AS '$libdir/mysm', 'getCurrentUser'
LANGUAGE C STRICT IMMUTABLE;

DROP FUNCTION IF EXISTS mysql.session_user() cascade;
CREATE OR REPLACE FUNCTION mysql.session_user()
RETURNS text
AS '$libdir/mysm', 'getSessionUser'
LANGUAGE C STRICT IMMUTABLE;

CREATE OR REPLACE FUNCTION mysql.get_column_key(pg_catalog.Oid, pg_catalog.text)
RETURNS pg_catalog.text
AS
$$
declare
    ret pg_catalog.text;
    tabOid pg_catalog.Oid;
    columnName pg_catalog.varchar(128);
    columnNameAttNum pg_catalog.text;
    indkeyAttNums pg_catalog.text[];
    element pg_catalog.text;
    indexs RECORD;
    columnIndexNum pg_catalog.int4;
BEGIN
    tabOid := $1;
    columnName := $2;

    ret := '';

    FOR indexs IN
        select attnum from pg_attribute where attrelid = tabOid and attname = columnName
    LOOP
        columnNameAttNum := indexs.attnum::pg_catalog.text;
    END LOOP;

    FOR indexs IN
        select ind.indrelid, ind.indkey, ind.indnkeyatts, ind.indisunique, ind.indisprimary
            from pg_index ind where (ind.indrelid = tabOid)
    LOOP
        indkeyAttNums := string_to_array(indexs.indkey::pg_catalog.text, ' ');
        FOREACH element IN ARRAY indkeyAttNums LOOP
            if (columnNameAttNum = element) then
                if (indexs.indisprimary = 1) then
                    ret := "PRI";
                    exit;
                else
                    if (indexs.indisunique = 1) then
                        columnIndexNum := pg_catalog.position(indexs.indkey::text, ' ');
                        if (0 = columnIndexNum) then
                            columnIndexNum := 1;
                        else
                            columnIndexNum := 2;
                        end if;
                        if (1 = columnIndexNum) then
                            ret := "UNI";
                            exit;
                        else
                            ret := "MUL";
                        end if;
                    else
                        if (indexs.indkey is not null) and (indexs.indkey::text != '') then
                            ret := "MUL";
                        end if;
                    end if;
                end if;
            end if;
        END LOOP;

        if (ret != '') then
            exit;
        end if;
    END LOOP;

    return ret;
END;
$$
IMMUTABLE STRICT LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mysql.amend_def_val(pg_catalog.text)
RETURNS pg_catalog.text
AS
$$
DECLARE
    ret pg_catalog.text;
    tmp pg_catalog.int4;
BEGIN
    tmp := 0;
    tmp := position('nextval' in $1);
    if 1 = tmp then
        ret = null;
    else
        tmp := 0;
        tmp := position('::' in $1);
        if 0 < tmp then
            ret = substring($1 from 1 for (tmp - 1));
            if lower(ret) = 'null' then
                ret = null;
            end if;
        else
            ret = $1;
        end if;
    end if;
    return ret;
END
$$
strict language 'plpgsql';

DROP VIEW IF EXISTS mys_informa_schema.columns CASCADE;
CREATE OR REPLACE VIEW mys_informa_schema.columns AS
SELECT
    'def'::varchar(256) as TABLE_CATALOG,
    (select ns.nspname from pg_catalog.pg_namespace ns where ns.oid = (select cl.relnamespace from pg_catalog.pg_class cl where cl.oid = att.attrelid))::varchar(256) as TABLE_SCHEMA,
    (select cl.relname from pg_catalog.pg_class cl where cl.oid = att.attrelid)::varchar(256) as TABLE_NAME,
    att.attname::varchar(256) as COLUMN_NAME,
    att.attnum::bigint as ORDINAL_POSITION,
    (mysql.amend_def_val(pg_get_expr((select ad.adbin from pg_catalog.pg_attrdef ad where ad.adnum = att.attnum and ad.adrelid = att.attrelid), att.attrelid)))::text as COLUMN_DEFAULT,
    (case when att.attnotnull then 'NO' else 'YES' end)::varchar(8) as IS_NULLABLE,
    (select
        case
            when ty.typname='tinyint' then 'tinyint'
            when ty.typname='tinyint signed' then 'tinyint signed'
            when ty.typname='tinyint unsigned' then 'tinyint unsigned'
            when ty.typname='smallint' then 'smallint'
            when ty.typname='smallint signed' then 'smallint signed'
            when ty.typname='smallint unsigned' then 'smallint unsigned'
            when ty.typname='mediumint' then 'mediumint'
            when ty.typname='mediumint signed' then 'mediumint signed'
            when ty.typname='mediumint unsigned' then 'mediumint unsigned'
            when ty.typname='int4' then 'int'
            when ty.typname='int signed' then 'int signed'
            when ty.typname='int unsigned' then 'int unsigned'
            when ty.typname='int8' then 'bigint'
            when ty.typname='bigint signed' then 'bigint signed'
            when ty.typname='bigint unsigned' then 'bigint unsigned'
            when ty.typname='varchar' then 'varchar'
            when ty.typname='bpchar' then 'char'
            when ty.typname='text' then 'text'
            when ty.typname='blob' then 'blob'
            when ty.typname='time' then 'time'
            when ty.typname='date' then 'date'
            when ty.typname='datetime' then 'datetime'
            when ty.typname='timestamp' then 'timestamp'
            when ty.typname='bit' then 'bit'
            when ty.typname='varbit' then 'bit'
            when ty.typname='binary' then 'binary'
            when ty.typname='varbinary' then 'varbinary'
            when ty.typname='tinyblob' then 'tinyblob'
            when ty.typname='blob' then 'blob'
            when ty.typname='mediumblob' then 'mediumblob'
            when ty.typname='longblob' then 'longblob'
            when mysql.left(ty.typname, 5)='float' then 'float'
            when ty.typname='double' then 'double'
            when ty.typname='decimal' then 'decimal'
            when ty.typname='numeric' then 'decimal'
            when ty.typname='real' then 'double'
            when ty.typname='year_' then 'year'
            else ty.typname
        end
        from pg_catalog.pg_type ty
        where att.atttypid = ty.oid)::varchar(64) as DATA_TYPE,
    65535::bigint as CHARACTER_MAXIMUM_LENGTH,
    65535::bigint as CHARACTER_OCTET_LENGTH,
    NULL::bigint as NUMERIC_PRECISION,
    NULL::bigint as NUMERIC_SCALE,
    NULL::bigint as DATETIME_PRECISION,
    'utf8mb4'::varchar(256) as CHARACTER_SET_NAME,
    (select
        case
            when ty.typname='tinyint' then NULL
            when ty.typname='tinyint signed' then NULL
            when ty.typname='tinyint unsigned' then NULL
            when ty.typname='smallint' then NULL
            when ty.typname='smallint signed' then NULL
            when ty.typname='smallint unsigned' then NULL
            when ty.typname='mediumint' then NULL
            when ty.typname='mediumint signed' then NULL
            when ty.typname='mediumint unsigned' then NULL
            when ty.typname='int4' then NULL
            when ty.typname='int signed' then NULL
            when ty.typname='int unsigned' then NULL
            when ty.typname='int8' then NULL
            when ty.typname='bigint signed' then NULL
            when ty.typname='bigint unsigned' then NULL
            when ty.typname='date' then NULL
            when ty.typname='time' then NULL
            when ty.typname='datetime' then NULL
            when ty.typname='timestamp' then NULL
            when ty.typname='bit' then NULL
            when ty.typname='varbit' then NULL
            when ty.typname='binary' then NULL
            when ty.typname='varbinary' then NULL
            when ty.typname='tinyblob' then NULL
            when ty.typname='blob' then NULL
            when ty.typname='mediumblob' then NULL
            when ty.typname='longblob' then NULL
            when mysql.left(ty.typname, 5)='float' then NULL
            when ty.typname='double' then NULL
            when ty.typname='decimal' then NULL
            when ty.typname='numeric' then NULL
            when ty.typname='real' then NULL
            when ty.typname='year_' then NULL
            else 'utf8mb4_0900_ai_ci'
        end
        from pg_catalog.pg_type ty
        where att.atttypid = ty.oid)::varchar(256) as COLLATION_NAME,
    (select
        case
            when ty.typname='tinyint' then 'tinyint'
            when ty.typname='tinyint signed' then 'tinyint signed'
            when ty.typname='tinyint unsigned' then 'tinyint unsigned'
            when ty.typname='smallint' then 'smallint'
            when ty.typname='smallint signed' then 'smallint signed'
            when ty.typname='smallint unsigned' then 'smallint unsigned'
            when ty.typname='mediumint' then 'mediumint'
            when ty.typname='mediumint signed' then 'mediumint signed'
            when ty.typname='mediumint unsigned' then 'mediumint unsigned'
            when ty.typname='int4' then 'int(11)'
            when ty.typname='int signed' then 'int signed'
            when ty.typname='int unsigned' then 'int unsigned'
            when ty.typname='int8' then 'bigint'
            when ty.typname='bigint signed' then 'bigint signed'
            when ty.typname='bigint unsigned' then 'bigint unsigned'
            when ty.typname='varchar' then pg_catalog.concat('varchar', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character varying', ''))
            when ty.typname='bpchar' then pg_catalog.concat('char', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character', ''))
            when ty.typname='text' then 'text'
            when ty.typname='date' then 'date'
            when ty.typname='time' then 'time'
            when ty.typname='datetime' then 'datetime(6)'
            when ty.typname='timestamp' then (pg_catalog.concat('timestamp(', att.atttypmod, ')'))
            when ty.typname='bit' then (pg_catalog.concat('bit(', att.atttypmod, ')'))
            when ty.typname='varbit' and att.atttypmod != -1 then (pg_catalog.concat('bit(', att.atttypmod, ')')) 
            when ty.typname='varbit' and att.atttypmod = -1 then 'bit(1)' 
            when ty.typname='binary' then 'binary'
            when ty.typname='varbinary' then 'varbinary'
            when ty.typname='tinyblob' then 'tinyblob'
            when ty.typname='blob' then 'blob'
            when ty.typname='mediumblob' then 'mediumblob'
            when ty.typname='longblob' then 'longblob'
            when mysql.left(ty.typname, 5)='float' then 'float'
            when ty.typname='double' then 'double'
            when ty.typname='decimal' then 'decimal'
            when ty.typname='numeric' then 'decimal'
            when ty.typname='real' then 'double'
            when ty.typname='year_' then 'year'
            else ty.typname
        end
        from pg_catalog.pg_type ty
        where att.atttypid = ty.oid)::text as COLUMN_TYPE,
    (mysql.get_column_key(att.attrelid, att.attname))::varchar(256) as COLUMN_KEY,
    (mysql.get_column_extra(mysql.amend_def_val_for_internal(pg_get_expr((select ad.adbin from pg_catalog.pg_attrdef ad where ad.adnum = att.attnum and ad.adrelid = att.attrelid), att.attrelid))))::text as EXTRA,
    'select,insert,update,references'::varchar(256) as PRIVILEGES,
    col_description(att.attrelid, att.attnum)::varchar(512) as COLUMN_COMMENT,
    ''::text as GENERATION_EXPRESSION,
    1::int as SRS_ID
FROM pg_catalog.pg_attribute att
WHERE 16384 <= att.attrelid and att.attname != 'tableoid' and att.attname != 'cmax' and
      att.attname != 'xmax' and att.attname != 'cmin' and att.attname != 'xmin' and
      att.attname != 'ctid' and att.attname not like '%pg.dropped.%'
order by att.attnum;

DROP FUNCTION IF EXISTS mysql.show_table_columns(pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_table_columns(pg_catalog.text, pg_catalog.text)
RETURNS setof RECORD
AS
$$
DECLARE
    schemaName pg_catalog.varchar(128);
    tableName pg_catalog.varchar(128);
    schOid pg_catalog.Oid;
    tabOid pg_catalog.Oid;
    sch RECORD;
    tab RECORD;
    columns RECORD;
BEGIN
    if ($1 is not null) then
        schemaName := $1;
    else
        schemaName := (select database());
    end if;
    if ($2 is not null) then
        tableName := $2;
    else
        raise EXCEPTION 'invalid table name';
    end if;

    schOid := 0;
    tabOid := 0;

    FOR sch IN
        select oid from pg_namespace where nspname = schemaName
    LOOP
        schOid := sch.oid;
    END LOOP;
    if (schOid = 0) then
        raise EXCEPTION 'invalid schema name';
    end if;

    FOR tab IN
        select oid from pg_class where (16384 <= oid) and (relname = tableName) and (relnamespace = schOid)
    LOOP
        tabOid := tab.oid;
    END LOOP;
    if (tabOid = 0) then
        raise EXCEPTION 'invalid table name';
    end if;

    FOR columns IN
        select
            att.attname::varchar(256) as Field,
            (select
                case
                    when ty.typname='tinyint' then 'tinyint'
                    when ty.typname='tinyint signed' then 'tinyint signed'
                    when ty.typname='tinyint unsigned' then 'tinyint unsigned'
                    when ty.typname='smallint' then 'smallint'
                    when ty.typname='smallint signed' then 'smallint signed'
                    when ty.typname='smallint unsigned' then 'smallint unsigned'
                    when ty.typname='mediumint' then 'mediumint'
                    when ty.typname='mediumint signed' then 'mediumint signed'
                    when ty.typname='mediumint unsigned' then 'mediumint unsigned'
                    when ty.typname='int4' then 'int(11)'
                    when ty.typname='int signed' then 'int signed'
                    when ty.typname='int unsigned' then 'int unsigned'
                    when ty.typname='int8' then 'bigint'
                    when ty.typname='bigint signed' then 'bigint signed'
                    when ty.typname='bigint unsigned' then 'bigint unsigned'
                    when ty.typname='varchar' then pg_catalog.concat('varchar', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character varying', ''))
                    when ty.typname='bpchar' then pg_catalog.concat('char', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character', ''))
                    when ty.typname='text' then 'text'
                    when ty.typname='date' then 'date'
                    when ty.typname='time' then 'time'
                    when ty.typname='datetime' then 'datetime(6)'
                    when ty.typname='timestamp' then (pg_catalog.concat('timestamp(', att.atttypmod, ')'))
                    when ty.typname='bit' then (pg_catalog.concat('bit(', att.atttypmod, ')'))
                    when ty.typname='varbit' and att.atttypmod != -1 then (pg_catalog.concat('bit(', att.atttypmod, ')')) 
                    when ty.typname='varbit' and att.atttypmod = -1 then 'bit(1)' 
                    when ty.typname='binary' then 'binary'
                    when ty.typname='varbinary' then 'varbinary'
                    when ty.typname='tinyblob' then 'tinyblob'
                    when ty.typname='blob' then 'blob'
                    when ty.typname='mediumblob' then 'mediumblob'
                    when ty.typname='longblob' then 'longblob'
                    when mysql.left(ty.typname, 5)='float' then 'float'
                    when ty.typname='double' then 'double'
                    when ty.typname='decimal' then 'decimal'
                    when ty.typname='numeric' then 'decimal'
                    when ty.typname='real' then 'double'
                    when ty.typname='year_' then 'year'
                    else ty.typname
                end
                from pg_catalog.pg_type ty
                where att.atttypid = ty.oid)::varchar(64) as Type,
            (case when att.attnotnull then 'NO' else 'YES' end)::varchar(8) as Null,
            (mysql.get_column_key(att.attrelid, att.attname))::varchar(256) as Key,
            (mysql.amend_def_val(pg_get_expr((select ad.adbin from pg_catalog.pg_attrdef ad where ad.adnum = att.attnum and ad.adrelid = att.attrelid), tabOid)))::text as Default,
            (mysql.get_column_extra(mysql.amend_def_val_for_internal(pg_get_expr((select ad.adbin from pg_catalog.pg_attrdef ad where ad.adnum = att.attnum and ad.adrelid = att.attrelid), tabOid))))::text as Extra
        FROM pg_catalog.pg_attribute att
        WHERE att.attrelid = tabOid and att.attname != 'tableoid' and att.attname != 'cmax' and
                att.attname != 'xmax' and att.attname != 'cmin' and att.attname != 'xmin' and
                att.attname != 'ctid' and att.attname not like '%pg.dropped.%'
                order by att.attnum
    LOOP
        return next columns;
    END LOOP;

    return;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

DROP FUNCTION IF EXISTS mysql.show_table_full_columns(pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_table_full_columns(pg_catalog.text, pg_catalog.text)
RETURNS setof RECORD
AS
$$
DECLARE
    schemaName pg_catalog.varchar(128);
    tableName pg_catalog.varchar(128);
    schOid pg_catalog.Oid;
    tabOid pg_catalog.Oid;
    sch RECORD;
    tab RECORD;
    columns RECORD;
BEGIN
    if ($1 is not null) then
        schemaName := $1;
    else
        schemaName := (select database());
    end if;
    if ($2 is not null) then
        tableName := $2;
    else
        raise EXCEPTION 'invalid table name';
    end if;

    schOid := 0;
    tabOid := 0;

    FOR sch IN
        select oid from pg_namespace where nspname = schemaName
    LOOP
        schOid := sch.oid;
    END LOOP;
    if (schOid = 0) then
        raise EXCEPTION 'invalid schema name';
    end if;

    FOR tab IN
        select oid from pg_class where (16384 <= oid) and (relname = tableName) and (relnamespace = schOid)
    LOOP
        tabOid := tab.oid;
    END LOOP;
    if (tabOid = 0) then
        raise EXCEPTION 'invalid table name';
    end if;

    FOR columns IN
        select
            att.attname::varchar(256) as Field,
            (select
                case
                    when ty.typname='tinyint' then 'tinyint'
                    when ty.typname='tinyint signed' then 'tinyint signed'
                    when ty.typname='tinyint unsigned' then 'tinyint unsigned'
                    when ty.typname='smallint' then 'smallint'
                    when ty.typname='smallint signed' then 'smallint signed'
                    when ty.typname='smallint unsigned' then 'smallint unsigned'
                    when ty.typname='mediumint' then 'mediumint'
                    when ty.typname='mediumint signed' then 'mediumint signed'
                    when ty.typname='mediumint unsigned' then 'mediumint unsigned'
                    when ty.typname='int4' then 'int(11)'
                    when ty.typname='int signed' then 'int signed'
                    when ty.typname='int unsigned' then 'int unsigned'
                    when ty.typname='int8' then 'bigint'
                    when ty.typname='bigint signed' then 'bigint signed'
                    when ty.typname='bigint unsigned' then 'bigint unsigned'
                    when ty.typname='varchar' then pg_catalog.concat('varchar', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character varying', ''))
                    when ty.typname='bpchar' then pg_catalog.concat('char', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character', ''))
                    when ty.typname='text' then 'text'
                    when ty.typname='date' then 'date'
                    when ty.typname='time' then 'time'
                    when ty.typname='datetime' then 'datetime(6)'
                    when ty.typname='timestamp' then (pg_catalog.concat('timestamp(', att.atttypmod, ')'))
                    when ty.typname='bit' then (pg_catalog.concat('bit(', att.atttypmod, ')'))
                    when ty.typname='varbit' and att.atttypmod != -1 then (pg_catalog.concat('bit(', att.atttypmod, ')')) 
                    when ty.typname='varbit' and att.atttypmod = -1 then 'bit(1)' 
                    when ty.typname='binary' then 'binary'
                    when ty.typname='varbinary' then 'varbinary'
                    when ty.typname='blob' then 'blob'
                    when ty.typname='mediumblob' then 'mediumblob'
                    when ty.typname='longblob' then 'longblob'
                    when mysql.left(ty.typname, 5)='float' then 'float'
                    when ty.typname='double' then 'double'
                    when ty.typname='decimal' then 'decimal'
                    when ty.typname='numeric' then 'decimal'
                    when ty.typname='real' then 'double'
                    when ty.typname='year_' then 'year'
                    else ty.typname
                end
                from pg_catalog.pg_type ty
                where att.atttypid = ty.oid)::varchar(64) as Type,
            (select colla.collname from pg_catalog.pg_collation colla where colla.oid = att.attcollation)::varchar(256) as Collation,
            (case when att.attnotnull then 'NO' else 'YES' end)::varchar(8) as Null,
            (mysql.get_column_key(att.attrelid, att.attname))::varchar(256) as Key,
            (mysql.amend_def_val(pg_get_expr((select ad.adbin from pg_catalog.pg_attrdef ad where ad.adnum = att.attnum and ad.adrelid = att.attrelid), tabOid)))::text as Default,
            (mysql.get_column_extra(mysql.amend_def_val_for_internal(pg_get_expr((select ad.adbin from pg_catalog.pg_attrdef ad where ad.adnum = att.attnum and ad.adrelid = att.attrelid), tabOid))))::text as Extra,
            'select,insert,update,references'::varchar(256) as Privileges,
            (case when col_description(att.attrelid, att.attnum) is not null then col_description(att.attrelid, att.attnum) else '' end)::varchar(512) as Comment
        FROM pg_catalog.pg_attribute att
        WHERE att.attrelid = tabOid and att.attname != 'tableoid' and att.attname != 'cmax' and
                att.attname != 'xmax' and att.attname != 'cmin' and att.attname != 'xmin' and
                att.attname != 'ctid' and att.attname not like '%pg.dropped.%'
                order by att.attnum
    LOOP
        return next columns;
    END LOOP;

    return;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

DROP FUNCTION IF EXISTS mysql.show_create_view_impl(pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_create_view_impl(pg_catalog.text, pg_catalog.text)
RETURNS pg_catalog.text
AS
$$
DECLARE
    ret pg_catalog.text;
    schName pg_catalog.text;
    vwName pg_catalog.text;
    records RECORD;
    definer pg_catalog.text;
    definition_ pg_catalog.text;
    sections pg_catalog.text[];
    subSections pg_catalog.text[];
    element pg_catalog.text;
    columnNum pg_catalog.int4;
BEGIN
    schName := $1;
    vwName := $2;
    columnNum := 0;

    FOR records IN
        select viewowner, definition from pg_views where schemaname = schName and viewname = vwName
    LOOP
        definer := records.viewowner;
        definition_ := records.definition;
    END LOOP;

    ret := pg_catalog.concat("CREATE ALGORITHM=UNDEFINED DEFINER=`", definer, "`@`%` SQL SECURITY DEFINER VIEW `", vwName, "` AS ");

    definition_ = pg_catalog.replace(definition_, '+', ' ');
    definition_ = pg_catalog.replace(definition_, '\n', ' ');
    definition_ = pg_catalog.replace(definition_, '\r', ' ');
    definition_ = pg_catalog.replace(definition_, ',', ' ');
    definition_ = pg_catalog.replace(definition_, ';', '');
    sections := string_to_array(definition_, ' ');
    FOREACH element IN ARRAY sections LOOP
        element := trim(both ' ' from element);
        if (element != '') then
            subSections := string_to_array(element, '.');
            if (array_length(subSections, 1) = 2) then
                if (0 < columnNum) then
                    ret := pg_catalog.concat(ret, ",");
                end if;
                ret := pg_catalog.concat(ret, "`");
                ret := pg_catalog.concat(ret, subSections[1]);
                ret := pg_catalog.concat(ret, "`.`");
                ret := pg_catalog.concat(ret, subSections[2]);
                ret := pg_catalog.concat(ret, "` AS `");
                ret := pg_catalog.concat(ret, subSections[2]);
                ret := pg_catalog.concat(ret, "`");
                columnNum := columnNum + 1;
            else
                if (subSections[1] = "SELECT") then
                    ret := pg_catalog.concat(ret, "select ");
                elsif (subSections[1] = "FROM") then
                    ret := pg_catalog.concat(ret, " from ");
                    columnNum := 0;
                else
                    ret := pg_catalog.concat(ret, "`");
                    ret := pg_catalog.concat(ret, subSections[1]);
                    ret := pg_catalog.concat(ret, "`");
                end if;
            end if;
        end if;
    END LOOP;

    return ret;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

DROP FUNCTION IF EXISTS mysql.show_create_table(pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_create_table(pg_catalog.text, pg_catalog.text)
RETURNS pg_catalog.text 
AS 
$$
declare 
    schName pg_catalog.text;
    tabName pg_catalog.text;
    schOid pg_catalog.Oid;
    tabOid pg_catalog.Oid;
    isTableOrView pg_catalog.int4;
    records RECORD;
BEGIN
    if ($1 is not null) then
        schName := $1;
    else
        schName := (select database());
    end if;
    if ($2 is not null) then
        tabName := $2;
    else
        raise EXCEPTION 'invalid table name';
    end if;

    schOid := 0;
    tabOid := 0;
    isTableOrView := 0;

    FOR records IN 
        select oid from pg_namespace where nspname = schName
    LOOP
        schOid := records.oid;
    END LOOP;
    if (schOid = 0) then 
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;

    FOR records IN 
        select viewname from pg_catalog.pg_views where (schemaname = schName) and (viewname = tabName) 
    LOOP
        isTableOrView := 2;
    END LOOP;

    if (isTableOrView = 0) then 
        FOR records IN 
            select oid from pg_class where (relname = tabName) and (relnamespace = schOid) 
        LOOP
            tabOid := records.oid;
            isTableOrView := 1;
        END LOOP;
    end if;

    if (isTableOrView = 1) then
        return mysql.show_create_table_impl(schOid, tabOid, schName, tabName);
    elsif (isTableOrView = 2) then
        return mysql.show_create_view_impl(schName, tabName);
    else
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

DROP FUNCTION IF EXISTS mysql.show_create_view(pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_create_view(pg_catalog.text, pg_catalog.text)
RETURNS pg_catalog.text
AS
$$
declare
    schName pg_catalog.text;
    tabName pg_catalog.text;
    schOid pg_catalog.Oid;
    isTableOrView pg_catalog.int4;
    records RECORD;
BEGIN
    if ($1 is not null) then
        schName := $1;
    else
        schName := (select database());
    end if;
    if ($2 is not null) then
        tabName := $2;
    else
        raise EXCEPTION 'invalid table name';
    end if;

    schOid := 0;
    isTableOrView := 0;

    FOR records IN
        select oid from pg_namespace where nspname = schName
    LOOP
        schOid := records.oid;
    END LOOP;
    if (schOid = 0) then
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;

    FOR records IN
        select viewname from pg_catalog.pg_views where (schemaname = schName) and (viewname = tabName)
    LOOP
        isTableOrView := 2;
    END LOOP;

    if (isTableOrView = 0) then
        FOR records IN
            select oid from pg_class where (relname = tabName) and (relnamespace = schOid)
        LOOP
            isTableOrView := 1;
        END LOOP;
    end if;

    if (isTableOrView = 1) then
        raise EXCEPTION '''%.%'' is not VIEW', schName, tabName;
    elsif (isTableOrView = 2) then
        return mysql.show_create_view_impl(schName, tabName);
    else
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mysql.show_table_indexs(pg_catalog.text, pg_catalog.text)
RETURNS setof RECORD
AS
$$
DECLARE
    schName pg_catalog.text;
    tabName pg_catalog.text;
    schOid pg_catalog.Oid;
    tabOid pg_catalog.Oid;
    keys pg_catalog.int4[];
    element pg_catalog.int4;
    records RECORD;
    subRecords RECORD;
BEGIN
    if ($1 is not null) then
        schName := $1;
    else
        schName := (select database());
    end if;
    if ($2 is not null) then
        tabName := $2;
    else
        raise EXCEPTION 'invalid table name';
    end if;

    schOid := 0;
    tabOid := 0;

    FOR records IN
        select oid from pg_namespace where nspname = schName
    LOOP
        schOid := records.oid;
    END LOOP;
    if (schOid = 0) then
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;

    FOR records IN
        select oid from pg_class where (16384 <= oid) and (relname = tabName) and (relnamespace = schOid)
    LOOP
        tabOid := records.oid;
    END LOOP;
    if (tabOid = 0) then
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;

    FOR records IN
        select ind.indexrelid, ind.indkey, ind.indisunique FROM pg_catalog.pg_index ind WHERE ind.indrelid = tabOid
    LOOP
        keys := string_to_array(records.indkey::text, ' ');
        FOREACH element IN ARRAY keys LOOP
            FOR subRecords IN
                select
                    (select cl.relname from pg_class cl where (cl.oid = tabOid))::varchar(256) as table_name,
                    (case when records.indisunique = 1 then 0 else 1 end)::int as Non_unique,
                    (select case when right(cl.relname, 5) = '_pkey' then 'PRIMARY' else cl.relname end from pg_class cl where (cl.oid = records.indexrelid))::varchar(256) as key_name,
                    (mysql.get_seq_in_index(att.attnum::pg_catalog.text, records.indkey))::int as Seq_in_index,
                    att.attname::varchar(256) as Column_name,
                    'A'::varchar(256) as Collation,
                    0::int as Cardinality,
                    NULL::int as Sub_part,
                    NULL::varchar(256) as Packed,
                    (case when att.attnotnull then '' else 'YES' end)::varchar(8) as _null,
                    (select am.amname from pg_am am where am.oid = (select cl.relam from pg_class cl where cl.oid = records.indexrelid))::varchar(256) as Index_type,
                    ''::varchar(512) as _comment,
                    ''::varchar(512) as Index_comment
                from pg_catalog.pg_attribute att
                where att.attrelid = tabOid and att.attnum = element
            LOOP
                return next subRecords;
            END LOOP;
        END LOOP;
    END LOOP;

    --XFOR records IN
    --X    select con.conrelid, con.conname, con.conkey FROM pg_catalog.pg_constraint con WHERE con.conrelid = tabOid and con.contype = 'f'
    --XLOOP
    --X    FOREACH element IN ARRAY records.conkey LOOP
    --X        FOR subRecords IN
    --X            select
    --X                (select cl.relname from pg_class cl where (cl.oid = records.conrelid))::varchar(256) as table_name,
    --X                1::int as Non_unique,
    --X                records.conname::varchar(256) as key_name,
    --X                1::int as Seq_in_index,
    --X                (select att.attname from pg_attribute att where (att.attnum = records.conkey[1]) and (att.attrelid = tabOid))::varchar(256) as Column_name,
    --X                'A'::varchar(256) as Collation,
    --X                0::int as Cardinality,
    --X                NULL::int as Sub_part,
    --X                NULL::varchar(256) as Packed,
    --X                ''::varchar(8) as _null,
    --X                'BTREE'::varchar(256) as Index_type,
    --X                ''::varchar(512) as _comment,
    --X                ''::varchar(512) as Index_comment
    --X            from pg_catalog.pg_attribute att
    --X            where att.attrelid = tabOid and att.attnum = element
    --X        LOOP
    --X            return next subRecords;
    --X        END LOOP;
    --X    END LOOP;
    --XEND LOOP;

    return;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

DROP FUNCTION IF EXISTS mysql.show_create_table_impl(pg_catalog.Oid, pg_catalog.Oid,
                                                        pg_catalog.text, pg_catalog.text) cascade;
CREATE OR REPLACE FUNCTION mysql.show_create_table_impl(pg_catalog.Oid, pg_catalog.Oid,
                                                        pg_catalog.text, pg_catalog.text)
RETURNS pg_catalog.text
AS
$$
DECLARE
    ret pg_catalog.text;
    schOid pg_catalog.Oid;
    tabOid pg_catalog.Oid;
    schName pg_catalog.text;
    tabName pg_catalog.text;
    columnIndex pg_catalog.int4;
    autoInc pg_catalog.int8;
    tmp pg_catalog.int4;
    tableComment pg_catalog.text;
    columnNames pg_catalog.text;
    columnNums pg_catalog.text;
    records RECORD;
BEGIN
    schOid := $1;
    tabOid := $2;
    schName := $3;
    tabName := $4;
    columnIndex := 0;

    ret := pg_catalog.concat('CREATE TABLE `', tabName, '` (');

    FOR records IN
        select att.attname as column_name,
                (pg_get_expr((select ad.adbin from pg_catalog.pg_attrdef ad where ad.adrelid = tabOid and ad.adnum = att.attnum), tabOid)) as column_default,
                (case when att.attnotnull then 'NO' else 'YES' end) as is_nullable,
                (select
                    case
                        when ty.typname='tinyint' then 'tinyint'
                        when ty.typname='tinyint signed' then 'tinyint signed'
                        when ty.typname='tinyint unsigned' then 'tinyint unsigned'
                        when ty.typname='smallint' then 'smallint'
                        when ty.typname='smallint signed' then 'smallint signed'
                        when ty.typname='smallint unsigned' then 'smallint unsigned'
                        when ty.typname='mediumint' then 'mediumint'
                        when ty.typname='mediumint signed' then 'mediumint signed'
                        when ty.typname='mediumint unsigned' then 'mediumint unsigned'
                        when ty.typname='int4' then 'int(11)'
                        when ty.typname='int signed' then 'int signed'
                        when ty.typname='int unsigned' then 'int unsigned'
                        when ty.typname='int8' then 'bigint'
                        when ty.typname='bigint signed' then 'bigint signed'
                        when ty.typname='bigint unsigned' then 'bigint unsigned'
                        when ty.typname='varchar' then pg_catalog.concat('varchar', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character varying', ''))
                        when ty.typname='bpchar' then pg_catalog.concat('char', pg_catalog.replace(format_type(att.atttypid, att.atttypmod), 'character', ''))
                        when ty.typname='text' then 'text'
                        when ty.typname='date' then 'date'
                        when ty.typname='time' then 'time'
                        when ty.typname='datetime' then 'datetime(6)'
                        when ty.typname='timestamp' then (pg_catalog.concat('timestamp(', att.atttypmod, ')'))
                        when ty.typname='bit' then (pg_catalog.concat('bit(', att.atttypmod, ')'))
                        when ty.typname='varbit' and att.atttypmod != -1 then (pg_catalog.concat('bit(', att.atttypmod, ')')) 
                        when ty.typname='varbit' and att.atttypmod = -1 then 'bit(1)' 
                        when ty.typname='binary' then 'binary'
                        when ty.typname='varbinary' then 'varbinary'
                        when ty.typname='tinyblob' then 'tinyblob'
                        when ty.typname='blob' then 'blob'
                        when ty.typname='mediumblob' then 'mediumblob'
                        when ty.typname='longblob' then 'longblob'
                        when mysql.left(ty.typname, 5)='float' then 'float'
                        when ty.typname='double' then 'double'
                        when ty.typname='decimal' then 'decimal'
                        when ty.typname='numeric' then 'decimal'
                        when ty.typname='real' then 'double'
                        when ty.typname='year_' then 'year'
                        else ty.typname
                    end
                    from pg_catalog.pg_type ty
                    where att.atttypid = ty.oid)::varchar(64) as column_type,
                col_description(att.attrelid, att.attnum) as column_comment,
                att.attnum::int4 as attnum,
                (select coll.collname from pg_collation coll where coll.oid = att.attcollation)::varchar(128) as column_collation
            from pg_catalog.pg_attribute att
            WHERE att.attrelid = tabOid and 0 < att.attnum and att.attisdropped = false
    LOOP
        if (0 < records.attnum) then
            if (0 < columnIndex) then
                ret := pg_catalog.concat(ret, ',\n  ');
            else
                ret := pg_catalog.concat(ret, '\n  ');
            end if;

            ret := pg_catalog.concat(ret, '`');
            ret := pg_catalog.concat(ret, records.column_name);
            ret := pg_catalog.concat(ret, '`');
            ret := pg_catalog.concat(ret, ' ', records.column_type);
            if (records.is_nullable = 'NO') then
                ret := pg_catalog.concat(ret, ' NOT NULL');
            end if;
            if (records.column_default is not null) then
                if (0 < position('nextval(' in records.column_default)) then
                    ret := pg_catalog.concat(ret, ' AUTO_INCREMENT');
                    execute format('select max(%s) from %I.%I', records.column_name, schName, tabName)
                    into autoInc;
                else
                    tmp := position('::character varying' in records.column_default);
                    if (0 < tmp) then
                        ret := pg_catalog.concat(ret, ' DEFAULT ', substring(records.column_default from 1 for (tmp - 1)));
                    else
                        ret := pg_catalog.concat(ret, ' DEFAULT ', records.column_default);
                    end if;
                end if;
            else
                if (records.is_nullable != 'NO') then
                    ret := pg_catalog.concat(ret, ' DEFAULT NULL');
                end if;
            end if;

            if (records.column_collation is not null) then
                ret := pg_catalog.concat(ret, ' COLLATE ', records.column_collation);
            end if;

            if (records.column_comment is not null) then
                ret := pg_catalog.concat(ret, ' COMMENT \'', records.column_comment, '\'');
            end if;

            columnIndex := columnIndex + 1;
        end if;
    END LOOP;

    FOR records IN
        --select cl.relname, ind.indrelid, ind.indkey, ind.indnatts, ind.indnkeyatts, ind.indisunique, ind.indisprimary
        --    from pg_class cl,
        --        (select * from pg_index where indrelid = tabOid) ind
        --    where cl.oid = ind.indexrelid
        select ind.indrelid, ind.indkey, ind.indnatts, ind.indnkeyatts, ind.indisunique, ind.indisprimary, (select cl.relname from pg_class cl where cl.oid = ind.indexrelid) as indname
            from pg_index ind where ind.indrelid = tabOid
        --select ind.indrelid, ind.indkey, ind.indnatts, ind.indnkeyatts, ind.indisunique, ind.indisprimary, cl.relname
        --    from pg_index ind join pg_class cl on ind.indrelid = cl.oid
        --    where ind.indrelid = tabOid and cl.oid = tabOid
    LOOP
        ret := pg_catalog.concat(ret, ',\n  ');
        columnNums := pg_catalog.replace(records.indkey::pg_catalog.text, ' '::pg_catalog.text, ','::pg_catalog.text);
        --execute format('select GROUP_CONCAT(attname separator \'`,`\')
        --                    from pg_attribute
        --                    where attrelid = %s and attnum in (%s)',
        --               records.indrelid, columnNums)
        execute format('select pg_catalog.string_agg(attname, ''`,`'') from pg_attribute where attrelid = %s and attnum in (%s)',
                       records.indrelid, columnNums)
            into columnNames;
        if (records.indisprimary = 1) then
            ret := pg_catalog.concat(ret, 'PRIMARY KEY (`', columnNames, '`)');
        elsif (records.indisunique = 1) then
            ret := pg_catalog.concat(ret, 'UNIQUE KEY `', records.indname, '`(`', columnNames, '`)');
        else
            ret := pg_catalog.concat(ret, 'KEY `', records.indname, '`(`', columnNames, '`)');
        end if;
    END LOOP;

    FOR records IN
        select
            cons.conname,
            --(select group_concat(att.attname separator ',') from pg_attribute att where (0 < array_position(cons.conkey, att.attnum)) and (att.attrelid = tabOId)) as column_name,
            (select pg_catalog.string_agg(att.attname, ',') from pg_attribute att where (0 < array_position(cons.conkey, att.attnum)) and (att.attrelid = tabOId)) as column_name,
            (select cl.relname from pg_class cl where (cl.oid = cons.confrelid)) as ref_table_name,
            --(select group_concat(att.attname separator ',') from pg_attribute att where (0 < array_position(cons.confkey, att.attnum)) and (att.attrelid = cons.confrelid)) as ref_column_name,
            (select pg_catalog.string_agg(att.attname, ',') from pg_attribute att where (0 < array_position(cons.confkey, att.attnum)) and (att.attrelid = cons.confrelid)) as ref_column_name,
            cons.confdeltype,
            cons.confupdtype
        from pg_constraint cons
        where (cons.contype = 'f') and (cons.conrelid = tabOid)
    LOOP
        ret := pg_catalog.concat(ret, ',\n  ');
        ret := pg_catalog.concat(ret, 'CONSTRAINT `');
        ret := pg_catalog.concat(ret, records.conname);
        ret := pg_catalog.concat(ret, '` FOREIGN KEY (`');
        ret := pg_catalog.concat(ret, records.column_name);
        ret := pg_catalog.concat(ret, '`) REFERENCES `');
        ret := pg_catalog.concat(ret, records.ref_table_name);
        ret := pg_catalog.concat(ret, '` (`');
        ret := pg_catalog.concat(ret, records.ref_column_name);
        ret := pg_catalog.concat(ret, '`) ON DELETE ');
        if (records.confdeltype = 'a') then
            ret := pg_catalog.concat(ret, 'NO ACTION ');
        elsif (records.confdeltype = 'c') then
            ret := pg_catalog.concat(ret, 'CASCADE ');
        elsif (records.confdeltype = 'd') then
            ret := pg_catalog.concat(ret, 'SET DEFAULT ');
        elsif (records.confdeltype = 'n') then
            ret := pg_catalog.concat(ret, 'SET NULL ');
        else
            ret := pg_catalog.concat(ret, 'RESTRICT ');
        end if;
        ret := pg_catalog.concat(ret, ' ON UPDATE ');
        if (records.confupdtype = 'a') then
            ret := pg_catalog.concat(ret, 'NO ACTION ');
        elsif (records.confupdtype = 'c') then
            ret := pg_catalog.concat(ret, 'CASCADE ');
        elsif (records.confupdtype = 'd') then
            ret := pg_catalog.concat(ret, 'SET DEFAULT ');
        elsif (records.confupdtype = 'n') then
            ret := pg_catalog.concat(ret, 'SET NULL ');
        else
            ret := pg_catalog.concat(ret, 'RESTRICT ');
        end if;
    END LOOP;

    FOR records IN
        select cons.conname, (select pg_get_constraintdef(cons.oid)) as consrc
        from pg_constraint cons
        where (cons.contype = 'c') and (cons.conrelid = tabOid)
    LOOP
        ret := pg_catalog.concat(ret, ',\n  ');
        ret := pg_catalog.concat(ret, 'CONSTRAINT ');
        ret := pg_catalog.concat(ret, records.conname);
        ret := pg_catalog.concat(ret, ' ');
        ret := pg_catalog.concat(ret, records.consrc);
    END LOOP;

    if (0 < autoInc) then
        autoInc := autoInc + 1;
        ret := pg_catalog.concat(ret, '\n) ENGINE=InnoDB AUTO_INCREMENT=', autoInc::text, ' DEFAULT CHARSET=utf8mb4');
    else
        ret := pg_catalog.concat(ret, '\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
    end if;

    tableComment := '';
    execute format('select ds.description from pg_description ds where ds.objoid = %s and objsubid = 0', tabOid) into tableComment;
    if (tableComment != '') then
        ret := pg_catalog.concat(ret, ' COMMENT ''', tableComment, '''');
    end if;

    return ret;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mysql.show_table_indexs_for_8(pg_catalog.text, pg_catalog.text)
RETURNS setof RECORD
AS
$$
DECLARE
    schName pg_catalog.text;
    tabName pg_catalog.text;
    schOid pg_catalog.Oid;
    tabOid pg_catalog.Oid;
    keys pg_catalog.int4[];
    element pg_catalog.int4;
    records RECORD;
    subRecords RECORD;
BEGIN
    if ($1 is not null) then
        schName := $1;
    else
        schName := (select database());
    end if;
    if ($2 is not null) then
        tabName := $2;
    else
        raise EXCEPTION 'invalid table name';
    end if;

    schOid := 0;
    tabOid := 0;

    FOR records IN
        select oid from pg_namespace where nspname = schName
    LOOP
        schOid := records.oid;
    END LOOP;
    if (schOid = 0) then
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;

    FOR records IN
        select oid from pg_class where (16384 <= oid) and (relname = tabName) and (relnamespace = schOid)
    LOOP
        tabOid := records.oid;
    END LOOP;
    if (tabOid = 0) then
        raise EXCEPTION 'Table ''%.%'' doesn''t exist', schName, tabName;
    end if;

    FOR records IN
        select ind.indexrelid, ind.indkey, ind.indisunique FROM pg_catalog.pg_index ind WHERE ind.indrelid = tabOid
    LOOP
        keys := string_to_array(records.indkey::text, ' ');
        FOREACH element IN ARRAY keys LOOP
            FOR subRecords IN
                select
                    (select cl.relname from pg_class cl where (cl.oid = tabOid))::varchar(256) as table_name,
                    (case when records.indisunique = 1 then 0 else 1 end)::int as Non_unique,
                    (select case when right(cl.relname, 5) = '_pkey' then 'PRIMARY' else cl.relname end from pg_class cl where (cl.oid = records.indexrelid))::varchar(256) as key_name,
                    (mysql.get_seq_in_index(att.attnum::pg_catalog.text, records.indkey))::int as Seq_in_index,
                    att.attname::varchar(256) as Column_name,
                    'A'::varchar(256) as Collation,
                    0::int as Cardinality,
                    NULL::int as Sub_part,
                    NULL::varchar(256) as Packed,
                    (case when att.attnotnull then '' else 'YES' end)::varchar(8) as _null,
                    (select am.amname from pg_am am where am.oid = (select cl.relam from pg_class cl where cl.oid = records.indexrelid))::varchar(256) as Index_type,
                    ''::varchar(512) as _comment,
                    ''::varchar(512) as Index_comment,
                    'YES'::varchar(64) as Visible,
                    NULL::varchar(512) as Expression
                from pg_catalog.pg_attribute att
                where att.attrelid = tabOid and att.attnum = element
            LOOP
                return next subRecords;
            END LOOP;
        END LOOP;
    END LOOP;

    --XFOR records IN
    --X    select con.conrelid, con.conname, con.conkey FROM pg_catalog.pg_constraint con WHERE con.conrelid = tabOid and con.contype = 'f'
    --XLOOP
    --X    FOREACH element IN ARRAY records.conkey LOOP
    --X        FOR subRecords IN
    --X            select
    --X                (select cl.relname from pg_class cl where (cl.oid = records.conrelid))::varchar(256) as table_name,
    --X                1::int as Non_unique,
    --X                records.conname::varchar(256) as key_name,
    --X                1::int as Seq_in_index,
    --X                (select att.attname from pg_attribute att where (att.attnum = records.conkey[1]) and (att.attrelid = tabOid))::varchar(256) as Column_name,
    --X                'A'::varchar(256) as Collation,
    --X                0::int as Cardinality,
    --X                NULL::int as Sub_part,
    --X                NULL::varchar(256) as Packed,
    --X                ''::varchar(8) as _null,
    --X                'BTREE'::varchar(256) as Index_type,
    --X                ''::varchar(512) as _comment,
    --X                ''::varchar(512) as Index_comment
    --X            from pg_catalog.pg_attribute att
    --X            where att.attrelid = tabOid and att.attnum = element
    --X        LOOP
    --X            return next subRecords;
    --X        END LOOP;
    --X    END LOOP;
    --XEND LOOP;

    return;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

drop table if exists mys_informa_schema.routines;
create view mys_informa_schema.routines as
    select
        proname::varchar(64) as specific_name,
        'def'::varchar(512) as routine_catalog,
        pronamespace::regnamespace::varchar(64) as routine_schema,
        proname::varchar(64) as routine_name,
        (case when pg_proc.prokind = 'f'::text THEN 'FUNCTION'  else 'PROCEDURE' end)::varchar(9) as routine_type,
        (case
            when pg_proc.prokind = 'f'::text THEN
                (select
                    case
                        when ty.typname='tinyint' then 'tinyint'
                        when ty.typname='tinyint signed' then 'tinyint signed'
                        when ty.typname='tinyint unsigned' then 'tinyint unsigned'
                        when ty.typname='smallint' then 'smallint'
                        when ty.typname='smallint signed' then 'smallint signed'
                        when ty.typname='smallint unsigned' then 'smallint unsigned'
                        when ty.typname='mediumint' then 'mediumint'
                        when ty.typname='mediumint signed' then 'mediumint signed'
                        when ty.typname='mediumint unsigned' then 'mediumint unsigned'
                        when ty.typname='int4' then 'int'
                        when ty.typname='int signed' then 'int signed'
                        when ty.typname='int unsigned' then 'int unsigned'
                        when ty.typname='int8' then 'bigint'
                        when ty.typname='bigint signed' then 'bigint signed'
                        when ty.typname='bigint unsigned' then 'bigint unsigned'
                        when ty.typname='varchar' then 'varchar'
                        when ty.typname='bpchar' then 'char'
                        when ty.typname='text' then 'text'
                        when ty.typname='date' then 'date'
                        when ty.typname='time' then 'time'
                        when ty.typname='datetime' then 'datetime'
                        when ty.typname='timestamp' then 'timestamp'
                        when ty.typname='bit' then 'bit'
                        when ty.typname='varbit' then 'bit'
                        when ty.typname='binary' then 'binary'
                        when ty.typname='varbinary' then 'varbinary'
                        when ty.typname='tinyblob' then 'tinyblob'
                        when ty.typname='blob' then 'blob'
                        when ty.typname='mediumblob' then 'mediumblob'
                        when ty.typname='longblob' then 'longblob'
                        when mysql.left(ty.typname, 5)='float' then 'float'
                        when ty.typname='double' then 'double'
                        when ty.typname='decimal' then 'decimal'
                        when ty.typname='numeric' then 'decimal'
                        when ty.typname='real' then 'double'
                        when ty.typname='year_' then 'year'
                        else ty.typname
                    end
                    from pg_catalog.pg_type ty
                    where ty.oid = prorettype)
            else ''
        end)::varchar(64) as data_type,
        null::int as CHARACTER_MAXIMUM_LENGTH,
        null::int as CHARACTER_OCTET_LENGTH,
        null::bigint as NUMERIC_PRECISION,
        null::int as NUMERIC_SCALE,
        null::bigint as DATETIME_PRECISION,
        null::varchar(64) as CHARACTER_SET_NAME,
        null::varchar(64) as COLLATION_NAME,
        (case
            when pg_proc.prokind = 'f'::text THEN
                (select
                    case
                        when ty.typname='tinyint' then 'tinyint'
                        when ty.typname='tinyint signed' then 'tinyint signed'
                        when ty.typname='tinyint unsigned' then 'tinyint unsigned'
                        when ty.typname='smallint' then 'smallint'
                        when ty.typname='smallint signed' then 'smallint signed'
                        when ty.typname='smallint unsigned' then 'smallint unsigned'
                        when ty.typname='mediumint' then 'mediumint'
                        when ty.typname='mediumint signed' then 'mediumint signed'
                        when ty.typname='mediumint unsigned' then 'mediumint unsigned'
                        when ty.typname='int4' then 'int'
                        when ty.typname='int signed' then 'int signed'
                        when ty.typname='int unsigned' then 'int unsigned'
                        when ty.typname='int8' then 'bigint'
                        when ty.typname='bigint signed' then 'bigint signed'
                        when ty.typname='bigint unsigned' then 'bigint unsigned'
                        when ty.typname='varchar' then 'varchar'
                        when ty.typname='bpchar' then 'char'
                        when ty.typname='text' then 'text'
                        when ty.typname='date' then 'date'
                        when ty.typname='time' then 'time'
                        when ty.typname='datetime' then 'datetime'
                        when ty.typname='timestamp' then 'timestamp'
                        when ty.typname='bit' then 'bit'
                        when ty.typname='varbit' then 'bit'
                        when ty.typname='binary' then 'binary'
                        when ty.typname='varbinary' then 'varbinary'
                        when ty.typname='tinyblob' then 'tinyblob'
                        when ty.typname='blob' then 'blob'
                        when ty.typname='mediumblob' then 'mediumblob'
                        when ty.typname='longblob' then 'longblob'
                        when mysql.left(ty.typname, 5)='float' then 'float'
                        when ty.typname='double' then 'double'
                        when ty.typname='decimal' then 'decimal'
                        when ty.typname='numeric' then 'decimal'
                        when ty.typname='real' then 'double'
                        when ty.typname='year_' then 'year'
                        else ty.typname
                    end
                    from pg_catalog.pg_type ty
                    where ty.oid = prorettype)
            else ''
        end)::text as DTD_IDENTIFIER,
        'SQL'::varchar(8) as ROUTINE_BODY,
        prosrc::text as ROUTINE_DEFINITION,
        null::varchar(64) as EXTERNAL_NAME,
        null::varchar(64) as EXTERNAL_LANGUAGE,
        'SQL'::varchar(8) as PARAMETER_STYLE,
        (case
            when provolatile='i' then 'YES'
            else 'NO'
        end)::varchar(3) as IS_DETERMINISTIC,
        'MODIFIES SQL DATA'::varchar(64) as SQL_DATA_ACCESS,
        null::varchar(64) as SQL_PATH,
        'DEFINER'::varchar(7) as SECURITY_TYPE,
        '2024-1-1'::mysql.datetime as CREATED,
        '2024-1-1'::mysql.datetime as LAST_ALTERED,
        'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION'::varchar(8192) as SQL_MODE,
        ''::text as ROUTINE_COMMENT,
        pg_catalog.concat(pg_get_userbyid(proowner), '@%')::varchar(93) as DEFINER,
        'utf8mb4'::varchar(32) as CHARACTER_SET_CLIENT,
        'utf8mb4_general_ci'::varchar(32) as COLLATION_CONNECTION,
        'utf8_general_ci'::varchar(32) as DATABASE_COLLATION
    from pg_proc
    where pronamespace not in('pg_catalog'::regnamespace, 'mysql'::regnamespace) and
          substring(proname from 1 for 21) != 'func_reset_serial_for' and
          prorettype != 2279;
-- 2279: trigger

create view mysql.proc as
    select
        pronamespace::regnamespace::char(64) as db,
        proname::char(64) as name,
        (case when pg_proc.prokind = 'f'::text THEN 'FUNCTION'  else 'PROCEDURE' end)::varchar(9) as type,
        proname::char(64) as specific_name,
        'SQL'::varchar(8) as language,
        'MODIFIES_SQL_DATA'::varchar(64) as sql_data_access,
        (case
            when provolatile='i' then 'YES'
            else 'NO'
        end)::varchar(3) as is_deterministic,
        'DEFINER'::varchar(7) as security_type,
        pg_get_function_arguments(oid)::mysql.blob as param_list,
        pg_get_function_result(oid)::mysql.blob as returns,
        prosrc::mysql.blob as body,
        pg_catalog.concat(pg_get_userbyid(proowner), '@%')::char(93) as definer,
        '2024-1-1'::timestamptz as created,
        '2024-1-1'::timestamptz as modified,
        'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION'::varchar(8192) as sql_mode,
        ''::text as comment,
        'utf8mb4'::char(32) as character_set_client,
        'utf8mb4_general_ci'::char(32) as collation_connection,
        'utf8_general_ci'::char(32) as db_collation,
        prosrc::mysql.blob as body_utf8
    from pg_proc
    where pronamespace not in('pg_catalog'::regnamespace, 'mysql'::regnamespace) and
          substring(proname from 1 for 21) != 'func_reset_serial_for' and
          prorettype != 2279;
-- 2279: trigger

DROP TABLE IF EXISTS mys_informa_schema.parameters_tmp;
CREATE table mys_informa_schema.parameters_tmp(
    SPECIFIC_CATALOG varchar(256),
    SPECIFIC_SCHEMA varchar(256),
    SPECIFIC_NAME varchar(256),
    ORDINAL_POSITION int,
    PARAMETER_MODE varchar(256),
    PARAMETER_NAME varchar(256),
    DATA_TYPE varchar(256),
    CHARACTER_MAXIMUM_LENGTH int,
    CHARACTER_OCTET_LENGTH int,
    NUMERIC_PRECISION bigint,
    NUMERIC_SCALE int,
    DATETIME_PRECISION bigint,
    CHARACTER_SET_NAME varchar(256),
    COLLATION_NAME varchar(256),
    DTD_IDENTIFIER text,
    ROUTINE_TYPE varchar(256)
);

CREATE OR REPLACE FUNCTION mysql.get_mysql_type_name(pg_catalog.oid)
RETURNS pg_catalog.text
AS
$$
DECLARE
    typeName pg_catalog.text;
BEGIN
    typeName := '';

    select typname into typeName from pg_catalog.pg_type where oid = $1;
    if typeName = 'tinyint' then 
        return 'tinyint';
    elsif typeName = 'tinyint signed' then 
        return 'tinyint signed';
    elsif typeName = 'tinyint unsigned' then  
        return 'tinyint unsigned';
    elsif typeName = 'smallint' then 
        return 'smallint';
    elsif typeName = 'smallint signed' then 
        return 'smallint signed';
    elsif typeName = 'smallint unsigned' then 
        return 'smallint unsigned';
    elsif typeName = 'mediumint' then 
        return 'mediumint';
    elsif typeName = 'mediumint signed' then 
        return 'mediumint signed';
    elsif typeName = 'mediumint unsigned' then 
        return 'mediumint unsigned';
    elsif typeName = 'int4' then 
        return 'int';
    elsif typeName = 'int signed' then 
        return 'int signed';
    elsif typeName = 'int unsigned' then 
        return 'int unsigned';
    elsif typeName = 'int8' then 
        return 'bigint';
    elsif typeName = 'bigint signed' then 
        return 'bigint signed';
    elsif typeName = 'bigint unsigned' then 
        return 'bigint unsigned';
    elsif typeName = 'varchar' then 
        return 'varchar';
    elsif typeName = 'bpchar' then 
        return 'char';
    elsif typeName = 'text' then 
        return 'text';
    elsif typeName = 'date' then 
        return 'date';
    elsif typeName = 'time' then 
        return 'time';
    elsif typeName = 'datetime' then 
        return 'datetime';
    elsif typeName = 'timestamp' then 
        return 'timestamp';
    elsif typeName = 'bit' then 
        return 'bit';
    elsif typeName = 'varbit' then 
        return 'bit';
    elsif typeName = 'binary' then 
        return 'binary';
    elsif typeName = 'varbinary' then 
        return 'varbinary';
    elsif typeName = 'tinyblob' then 
        return 'tinyblob';
    elsif typeName = 'blob' then 
        return 'blob';
    elsif typeName = 'mediumblob' then 
        return 'mediumblob';
    elsif typeName = 'longblob' then 
        return 'longblob';
    elsif mysql.left(typeName, 5) = 'float' then 
        return 'float';
    elsif typeName = 'double' then 
        return 'double';
    elsif typeName = 'decimal' then 
        return 'decimal';
    elsif typeName = 'numeric' then 
        return 'decimal';
    elsif typeName = 'real' then 
        return 'double';
    else  
        return typeName;
    end if;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION mysql.get_mysql_proc_arg_mode(pg_catalog.text)
RETURNS pg_catalog.text
AS
$$
BEGIN
    if $1 = 'i' then
        return 'IN';
    else
        return 'OUT';
    end if;
END;
$$
IMMUTABLE LANGUAGE plpgsql;

create or replace function mysql.get_funcs_procs_parameters()
RETURNS setof RECORD
AS
$$
DECLARE
    records RECORD;
    ordinalPosition int4;
    types pg_catalog.oid[];
    element pg_catalog.oid;
    argNum pg_catalog.int4;
    argIndex pg_catalog.int4;
BEGIN
    -- 清空临时view
    delete from mys_informa_schema.parameters_tmp;

    -- 读取 func信息，处理后插入临时view
    -- navicat_func2 | navicat      |         23 | 23 23       | {arg1,arg2}
    ordinalPosition := 0;
    FOR records IN
        select proname, pronamespace::regnamespace, prorettype, proargtypes, proargnames
        from pg_catalog.pg_proc
        where 16384 <= oid and prokind = 'f'
    LOOP
        if ordinalPosition = 0 then
            insert into mys_informa_schema.parameters_tmp values(
                'def',
                records.pronamespace,
                records.proname,
                ordinalPosition,
                null,
                null,
                mysql.get_mysql_type_name(records.prorettype),
                null,
                null,
                10,
                0,
                null,
                null,
                null,
                mysql.get_mysql_type_name(records.prorettype),
                'FUNCTION'
            );
        else
            IF records.proargtypes is not null THEN
                types := string_to_array(records.proargtypes::text, ' ');
                argIndex := 1;
                FOREACH element IN ARRAY types LOOP
                    Insert into mys_informa_schema.parameters_tmp values(
                        'def',
                        records.pronamespace,
                        records.proname,
                        ordinalPosition,
                        'IN',
                        records.proargnames[argIndex],
                        mysql.get_mysql_type_name(element),
                        null,
                        null,
                        10,
                        0,
                        null,
                        null,
                        null,
                        mysql.get_mysql_type_name(records.prorettype),
                        'FUNCTION'
                    );
                    argIndex := argIndex + 1;
                END LOOP;
            END IF;
        end if;
        ordinalPosition := ordinalPosition + 1;
    END LOOP;

    -- 读取 procc信息，处理后插入临时view
    -- navicat_proc2 | navicat      |  {23,23,23}     | {i,i,o}     | {arg1,arg2,arg3}
    ordinalPosition := 1;
    FOR records IN
        select proname, pronamespace::regnamespace, proallargtypes, proargmodes, proargnames
        from pg_catalog.pg_proc
        where 16384 <= oid and prokind = 'p'
    LOOP
        IF records.proallargtypes is not null THEN
            argNum := array_length(records.proallargtypes, 1);
            argIndex := 1;
            LOOP
                Insert into mys_informa_schema.parameters_tmp values(
                    'def',
                    records.pronamespace,
                    records.proname,
                    ordinalPosition,
                    mysql.get_mysql_proc_arg_mode(records.proargmodes[argIndex]),
                    records.proargnames[argIndex],
                    mysql.get_mysql_type_name(records.proallargtypes[argIndex]),
                    null,
                    null,
                    10,
                    0,
                    null,
                    null,
                    null,
                    mysql.get_mysql_type_name(records.proallargtypes[argIndex]),
                    'PROCEDURE'
                );
                ordinalPosition := ordinalPosition + 1;
                argIndex := argIndex + 1;

                EXIT WHEN argIndex > argNum;
            END LOOP;
        END IF;
    END LOOP;

    -- 读取临时表并插入parameters表
    FOR records IN
        select * from mys_informa_schema.parameters_tmp
    LOOP
        return next records;
    END LOOP;

    return;
END;
$$
VOLATILE LANGUAGE plpgsql;

drop view if exists mys_informa_schema.parameters;
CREATE view mys_informa_schema.parameters as
    select *
        from mysql.get_funcs_procs_parameters()
            as (
                SPECIFIC_CATALOG varchar(256),
                SPECIFIC_SCHEMA varchar(256),
                SPECIFIC_NAME varchar(256),
                ORDINAL_POSITION int,
                PARAMETER_MODE varchar(256),
                PARAMETER_NAME varchar(256),
                DATA_TYPE varchar(256),
                CHARACTER_MAXIMUM_LENGTH int,
                CHARACTER_OCTET_LENGTH int,
                NUMERIC_PRECISION bigint,
                NUMERIC_SCALE int,
                DATETIME_PRECISION bigint,
                CHARACTER_SET_NAME varchar(256),
                COLLATION_NAME varchar(256),
                DTD_IDENTIFIER text,
                ROUTINE_TYPE varchar(256)
            );

